import heapq
from collections import deque

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique nodes from keys and values
    all_nodes = set(deps.keys())
    for neighbors in deps.values():
        all_nodes.update(neighbors)

    # Build adjacency list and in-degree map
    # Edge direction: dependency -> dependent (u -> v means u must come before v)
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in deps.items():
        for dep in dependencies:
            # Add edge from dep to node
            adj[dep].append(node)
            in_degree[node] += 1

    # Initialize priority queue with nodes having 0 in-degree
    pq = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(pq, node)

    result = []

    while pq:
        # Pop the alphabetically smallest available node
        current = heapq.heappop(pq)
        result.append(current)

        # Update neighbors
        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(pq, neighbor)

    # If result doesn't include all nodes, there's a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result
