def wrap(text: str, width: int) -> list[str]:
    if not text or width <= 0:
        return []

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []

    for word in words:
        # Split long words into chunks of at most 'width' characters
        parts = [word[i:i+width] for i in range(0, len(word), width)]

        for part in parts:
            if not current_line:
                current_line.append(part)
            elif len(" ".join(current_line)) + 1 + len(part) <= width:
                current_line.append(part)
            else:
                lines.append(" ".join(current_line))
                current_line = [part]

    if current_line:
        lines.append(" ".join(current_line))

    return lines
