def deep_merge(base: dict, override: dict) -> dict:
    result = {}

    def _deep_copy_and_merge(obj, overrides):
        res = {}
        for k, v in obj.items():
            if k not in overrides:
                # Key only in base: deep copy recursively
                if isinstance(v, dict):
                    res[k] = {subk: deepcopy_val(subv) for subk, subv in v.items()}
                elif isinstance(v, list):
                    res[k] = [deepcopy_val(item) for item in v]
                else:
                    res[k] = v
            else:
                # Key in override
                o_v = overrides[k]
                if o_v is None:
                    continue  # Delete key
                elif isinstance(v, dict) and isinstance(o_v, dict):
                    res[k] = _deep_copy_and_merge(v, o_v)
                else:
                    # Replace with override value (deep copy if needed)
                    if isinstance(o_v, dict):
                        res[k] = {subk: deepcopy_val(subv) for subk, subv in o_v.items()}
                    elif isinstance(o_v, list):
                        res[k] = [deepcopy_val(item) for item in o_v]
                    else:
                        res[k] = o_v
        return res

    def deepcopy_val(val):
        if isinstance(val, dict):
            return {k: deepcopy_val(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [deepcopy_val(item) for item in val]
        else:
            return val

    # Start the process
    base_keys = set(base.keys())
    override_keys = set(override.keys())

    # Keys only in base (keep as-is, deep copied)
    for k in base_keys - override_keys:
        v = base[k]
        if isinstance(v, dict):
            result[k] = {sk: deepcopy_val(sv) for sk, sv in v.items()}
        elif isinstance(v, list):
            result[k] = [deepcopy_val(item) for item in v]
        else:
            result[k] = v

    # Keys in override (apply rules)
    for k, o_v in override.items():
        if o_v is None:
            continue
        if k in base and isinstance(base[k], dict) and isinstance(o_v, dict):
            result[k] = _deep_copy_and_merge(base[k], o_v)
        else:
            if isinstance(o_v, dict):
                result[k] = {sk: deepcopy_val(sv) for sk, sv in o_v.items()}
            elif isinstance(o_v, list):
                result[k] = [deepcopy_val(item) for item in o_v]
            else:
                result[k] = o_v

    return result
