def compact(n: int) -> str:
    import math

    if n < 1000:
        return str(n)

    # Define units and thresholds (before rounding adjustment)
    units = [(1_000_000_000, 'bi'), (1_000_000, 'mi'), (1_000, 'mil')]

    # Find appropriate unit before rounding to avoid repeated division
    for threshold, unit in units:
        if n >= threshold:
            divisor = threshold // 1000
            break
    else:
        return str(n)

    value = n / divisor

    # Round half up to 1 decimal place
    rounded_value = math.floor(value * 10 + 0.5) / 10

    # Format with one decimal place, then strip trailing comma-zero
    formatted = f"{rounded_value:,.1f}".replace('.', ',')
    if formatted.endswith(',0'):
        formatted = formatted[:-2]

    return formatted
