def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents cannot be negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    for w in weights:
        if w < 0:
            raise ValueError("weights cannot contain negative values")
    if sum(weights) == 0:
        raise ValueError("weights cannot all be zero")

    total_weight = sum(weights)
    n = len(weights)

    base = [(w * total_cents) // total_weight for w in weights]
    remainders = [(w * total_cents) % total_weight for w in weights]

    leftover = total_cents - sum(base)
    if leftover < 0:
        # This should not happen given the math, but safeguard against negative totals
        leftover = 0

    indices_with_remainder = list(range(n))
    indices_with_remainder.sort(key=lambda i: remainders[i], reverse=True)

    result = base[:]
    for i in range(leftover):
        result[indices_with_remainder[i]] += 1

    return result
