from decimal import Decimal, InvalidOperation

def parse_brl(s: str) -> Decimal:
    import re

    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    negative = False

    # Handle parentheses for negative numbers
    if s.startswith('(') and s.endswith(')'):
        negative = True
        s = s[1:-1].strip()
    elif s.startswith('-'):
        negative = True
        s = s[1:].strip()

    # Remove optional 'R$' prefix
    if s.upper().startswith('R$'):
        s = s[2:].strip()

    if not s:
        raise ValueError("Missing numeric value")

    # Split into integer and decimal parts
    if ',' in s:
        int_part, dec_part = s.rsplit(',', 1)
        if len(dec_part) != 2 or not dec_part.isdigit():
            raise ValueError("Invalid decimal part")
    else:
        int_part = s
        dec_part = '00'

    # Clean integer part: remove '.' thousand separators
    int_cleaned = int_part.replace('.', '')

    if not int_cleaned.isdigit() or (int_cleaned == '' and ',' in s):
        raise ValueError("Invalid integer part")

    # Format as standard decimal string
    num_str = f"{int_cleaned}.{dec_part}"

    try:
        result = Decimal(num_str)
    except InvalidOperation:
        raise ValueError("Failed to parse decimal")

    if negative:
        result = -result

    return result
