def wrap(text: str, width: int) -> list[str]:
    if width <= 0:
        return []

    raw_words = text.split()
    if not raw_words:
        return []

    segments = []
    for word in raw_words:
        if len(word) > width:
            i = 0
            while i < len(word):
                segments.append(word[i:i+width])
                i += width
        else:
            segments.append(word)

    lines = []
    current_line = []
    current_length = 0

    for seg in segments:
        seg_len = len(seg)
        if not current_line:
            current_line.append(seg)
            current_length = seg_len
        elif current_length + 1 + seg_len <= width:
            current_line.append(seg)
            current_length += 1 + seg_len
        else:
            lines.append(' '.join(current_line))
            current_line = [seg]
            current_length = seg_len

    if current_line:
        lines.append(' '.join(current_line))

    return lines
