def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    found_section = False
    found_key = False
    new_lines = []

    for line in lines:
        stripped = line.strip()

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1].strip()
            if current_section == section:
                found_section = True
            else:
                found_section = False
            new_lines.append(line)
            continue

        # If we are in the target section, check for the key
        if found_section and not stripped.startswith('#') and not stripped.startswith(';') and stripped:
            if '=' in stripped:
                k_part = stripped.split('=', 1)[0].strip()
                if k_part == key:
                    found_key = True
                    new_lines.append(f"{key} = {value}" + ('\n' if line.endswith('\n') else ''))
                    continue

        new_lines.append(line)

    if not found_section or not found_key:
        raise KeyError(f"Section '{section}' or key '{key}' not found")

    return ''.join(new_lines)
