    result = {}

    def copy_value(val):
        # Ensure we don't share nested mutable structures
        if isinstance(val, dict):
            return {k: copy_value(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [copy_value(item) for item in val]
        else:
            return val

    def merge(base_dict, override_dict):
        merged = {}
        # Start with all keys from base (copied to avoid sharing)
        for k, v in base_dict.items():
            merged[k] = copy_value(v)

        # Apply override rules
        for k, v in override_dict.items():
            if v is None:
                merged.pop(k, None)
            elif isinstance(v, dict) and k in base_dict and isinstance(base_dict.get(k), dict):
                # Recursively merge nested dicts
                merged[k] = merge(base_dict[k], v)
            else:
                # Replace (and copy to avoid sharing)
                merged[k] = copy_value(v)

        return merged

    return merge(base, override)
