from collections import deque

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique items
    all_items = set(deps.keys())
    for dependencies in deps.values():
        all_items.update(dependencies)

    # Initialize adjacency list and in-degree counts
    adj = {item: [] for item in all_items}
    in_degree = {item: 0 for item in all_items}

    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # Initialize heap with nodes having in-degree 0
    heap = [item for item in all_items if in_degree[item] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        current = heapq.heappop(heap)
        order.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(all_items):
        raise ValueError("Cycle detected")

    return order
