def find_Rotations(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    # Build KMP prefix table
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    # The smallest period is n - pi[n-1]
    period = n - pi[n - 1]

    # If the length is divisible by the period, then the minimum rotations is the period
    if n % period == 0:
        return period
    else:
        return n
